// Contrat d'entrée — gabarit commun (enveloppe@1). Toute entrée hors schéma arrête l'exécution : ni écriture ni envoi derrière.
const CONTRAT = 'lib-exemple-executer@1';
const REQUIS = ['contrat', 'organisation_id', 'simulation', 'cle_idempotence', 'trace', 'config', 'donnees'];
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
return $input.all().map((item) => {
  const e = item.json;
  const manque = REQUIS.filter((k) => !(k in e));
  const enTrop = Object.keys(e).filter((k) => !REQUIS.includes(k));
  if (manque.length || enTrop.length) throw new Error('contrat ' + CONTRAT + ' : manquants [' + manque.join(',') + '] en trop [' + enTrop.join(',') + ']');
  if (e.contrat !== CONTRAT) throw new Error('contrat attendu : ' + CONTRAT);
  if (!UUID.test(String(e.organisation_id))) throw new Error('organisation_id : uuid attendu');
  if (typeof e.simulation !== 'boolean') throw new Error('simulation : booléen attendu');
  if (typeof e.cle_idempotence !== 'string' || !e.cle_idempotence || e.cle_idempotence.length > 80) throw new Error('cle_idempotence : 1 à 80 caractères');
  if (!e.trace || typeof e.trace !== 'object' || !e.config || typeof e.config !== 'object' || !e.donnees || typeof e.donnees !== 'object') throw new Error('trace, config et donnees : objets attendus');
  return { json: e };
});

// Branche « simulation » : rien n'est écrit ni envoyé, l'effet prévu part au journal.
const e = $('Contrat d\'entrée').first().json;
return [{ json: { effets_prevus: [{ cible: e.donnees.cible ?? null, cle_idempotence: e.cle_idempotence }] } }];

// Contrat de sortie — gabarit commun (enveloppe@1) : le seul nœud final. effets_faits reste vide en simulation.
const CONTRAT = 'lib-exemple-executer@1';
const e = $('Contrat d\'entrée').first().json;
const passes = $input.all().map((i) => i.json);
const effetsPrevus = passes.flatMap((p) => Array.isArray(p.effets_prevus) ? p.effets_prevus : []);
const effetsFaits = e.simulation === true ? [] : passes.filter((p) => p.id || p.ref_id).map((p) => ({ ref_id: p.id ?? p.ref_id ?? null }));
return [{ json: {
  'contrat': CONTRAT,
  'statut': effetsFaits.length || effetsPrevus.length ? 'ok' : 'rien_a_faire',
  'cle_idempotence': e.cle_idempotence,
  'simulation': e.simulation,
  'resultat': null,
  'effets_prevus': effetsPrevus,
  'effets_faits': effetsFaits,
  'journal': [],
  'erreurs': [],
} }];
